-- Sales Explorer (portal page /management/sales-explorer.html), 25 Nov 2026.
-- Moves the Claude "DFL Sales Explorer" dashboard into the portal. Read-only: nothing existing is changed.
-- Generated by SC-Temp\area_review_build\sales_explorer\build_sql.ps1 from the dashboard's own queries.
--
-- 1. sales_explorer_can(): Scott only for now (25 Nov): the price approver, as for the Head of Sales page.
-- 2. sales_explorer_data(part, params): the dashboard's queries over public.mv_sales_explorer, filled with
--    quoted literals (format %L), so each call plans like the tested queries (about 1s for the biggest).
-- 3. Refresh now: rebuilding the summary takes ~45s, longer than a portal request may run (8s), so the
--    button only records a request; a once-a-minute cron job rebuilds when a request is waiting.

ALTER TABLE public.sales_explorer_meta ADD COLUMN IF NOT EXISTS requested_at timestamptz;

CREATE OR REPLACE FUNCTION public.sales_explorer_can()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT public.is_price_approver();
$$;

CREATE OR REPLACE FUNCTION public.sales_explorer_data(p_part text, p jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $fn$
DECLARE
  v_start  date := COALESCE((p->>'start')::date, date_trunc('year', current_date)::date);
  v_end    date := COALESCE((p->>'end')::date, current_date);
  v_pstart date := COALESCE((p->>'pstart')::date, (date_trunc('year', current_date) - interval '1 year')::date);
  v_pend   date := COALESCE((p->>'pend')::date, (current_date - interval '1 year')::date);
  v_usd    boolean := COALESCE((p->>'include_usd')::boolean, true);
  v_view   text := CASE WHEN p->>'rep_view' = 'then' THEN 'then' ELSE 'today' END;
  v_base text := $q$
WITH p AS (
  SELECT CAST(%1$L AS date) AS cs, CAST(%2$L AS date) AS ce,
         CAST(%3$L AS date) AS ps, CAST(%4$L AS date) AS pe
),
l AS (
  SELECT m.d, m.customer_id, m.inventory_id,
         CASE m.item_class WHEN '0' THEN 'NON-ITEM LINES' ELSE m.item_class END AS item_class,
         CASE m.rep WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN '0' THEN 'Unassigned' ELSE m.rep END AS rep,
         m.customer_name, m.description, m.rev, m.gp, m.qty,
         CASE WHEN m.d BETWEEN p.cs AND p.ce THEN 'c' ELSE 'p' END AS per
  FROM public.mv_sales_explorer m CROSS JOIN p
  WHERE (m.d BETWEEN p.cs AND p.ce OR m.d BETWEEN p.ps AND p.pe)
    AND (%5$s OR m.customer_id NOT IN ('C000007259', 'C000009702'))
),
cr0 AS (
  SELECT DISTINCT ON (customer_id) customer_id, rep AS then_rep
  FROM (SELECT customer_id, rep, SUM(rev) FILTER (WHERE per = 'c') AS rc, SUM(rev) AS rt FROM l GROUP BY 1, 2) x
  ORDER BY customer_id, rc DESC NULLS LAST, rt DESC
),
rec AS (
  SELECT DISTINCT ON (customer_id) customer_id, rep
  FROM (SELECT customer_id, CASE rep WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN '0' THEN 'Unassigned' ELSE rep END AS rep, SUM(rev) AS r
        FROM public.mv_sales_explorer WHERE d > CURRENT_DATE - 91 GROUP BY 1, 2) x
  WHERE r > 0
  ORDER BY customer_id, r DESC
),
ms AS (
  SELECT c.customer_id,
         MAX(CASE s.sp_name WHEN 'Kimberly Brown' THEN 'Oniel Carby' WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN 'Shallet Marsh.' THEN 'Shallet Marsh' ELSE s.sp_name END) AS rep
  FROM public.customers c JOIN public.salespersons s ON CAST(s.acumatica_numeric_id AS text) = CAST(c.salesperson_id AS text)
  WHERE s.is_active
  GROUP BY 1
),
cr AS (
  SELECT cr0.customer_id,
         CASE WHEN CAST(%6$L AS text) = 'then' THEN cr0.then_rep ELSE COALESCE(rec.rep, ms.rep, 'No current rep') END AS crep
  FROM cr0 LEFT JOIN rec USING (customer_id) LEFT JOIN ms USING (customer_id)
),
cm AS (
  SELECT customer_id, MAX(customer_name) AS cname, MAX(NULLIF(TRIM(customer_class), '')) AS cls
  FROM public.customers GROUP BY 1
),
f AS (
  SELECT l.*, cr.crep, COALESCE(cm.cls, 'UNASSIGNED') AS cls, COALESCE(cm.cname, l.customer_name) AS cname
  FROM l JOIN cr USING (customer_id) LEFT JOIN cm USING (customer_id)
  WHERE (CAST(%7$L AS text) IS NULL OR cr.crep = CAST(%7$L AS text))
    AND (CAST(%8$L AS text) IS NULL OR COALESCE(cm.cls, 'UNASSIGNED') = CAST(%8$L AS text))
    AND (CAST(%9$L AS text) IS NULL OR l.item_class = CAST(%9$L AS text))
)
$q$;
  q text;
  r jsonb;
BEGIN
  IF NOT public.sales_explorer_can() THEN
    RAISE EXCEPTION 'The Sales Explorer is not open to you yet.' USING ERRCODE = '42501';
  END IF;
  IF p_part = 'as_of' THEN
    SELECT to_jsonb(m) INTO r FROM (SELECT refreshed_at, source_synced_at, requested_at FROM public.sales_explorer_meta WHERE id = 1) m;
    RETURN COALESCE(r, '{}'::jsonb);
  END IF;
  q := CASE p_part
    WHEN 'options' THEN $q$
SELECT 'rep' AS kind, CASE rep WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN '0' THEN 'Unassigned' ELSE rep END AS value FROM public.mv_sales_explorer GROUP BY 2
UNION ALL
SELECT 'rep', 'No current rep'
UNION ALL
SELECT 'cls', COALESCE(NULLIF(TRIM(customer_class), ''), 'UNASSIGNED') FROM public.customers GROUP BY 2
UNION ALL
SELECT 'cat', CASE item_class WHEN '0' THEN 'NON-ITEM LINES' ELSE item_class END FROM public.mv_sales_explorer GROUP BY 2
ORDER BY 1, 2
$q$
    WHEN 'kpis' THEN v_base || $q$
SELECT a.*,
  CASE WHEN a.rev_p > 0 THEN ROUND(100 * (a.rev_c / a.rev_p - 1), 1) END AS rev_chg_pct,
  CASE WHEN a.gp_p > 0 THEN ROUND(100 * (a.gp_c / a.gp_p - 1), 1) END AS gp_chg_pct,
  ROUND(a.gp_pct_c - a.gp_pct_p, 1) AS gp_pct_chg_pts,
  CASE WHEN a.cust_p > 0 THEN ROUND(100.0 * a.cust_c / a.cust_p - 100, 1) END AS cust_chg_pct,
  CASE WHEN a.sku_p > 0 THEN ROUND(100.0 * a.sku_c / a.sku_p - 100, 1) END AS sku_chg_pct,
  CASE WHEN a.drops_p > 0 THEN ROUND(100.0 * a.drops_c / a.drops_p - 100, 1) END AS drops_chg_pct
FROM (
  SELECT
    ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
    ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
    ROUND(SUM(gp) FILTER (WHERE per = 'c')) AS gp_c,
    ROUND(SUM(gp) FILTER (WHERE per = 'p')) AS gp_p,
    ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct_c,
    ROUND(100 * SUM(gp) FILTER (WHERE per = 'p') / NULLIF(SUM(rev) FILTER (WHERE per = 'p'), 0), 1) AS gp_pct_p,
    COUNT(DISTINCT customer_id) FILTER (WHERE per = 'c') AS cust_c,
    COUNT(DISTINCT customer_id) FILTER (WHERE per = 'p') AS cust_p,
    COUNT(DISTINCT inventory_id) FILTER (WHERE per = 'c' AND inventory_id <> '') AS sku_c,
    COUNT(DISTINCT inventory_id) FILTER (WHERE per = 'p' AND inventory_id <> '') AS sku_p,
    COUNT(DISTINCT customer_id || '|' || d) FILTER (WHERE per = 'c') AS drops_c,
    COUNT(DISTINCT customer_id || '|' || d) FILTER (WHERE per = 'p') AS drops_p
  FROM f
) a
$q$
    WHEN 'monthly' THEN $q$
WITH p AS (
  SELECT CAST(%1$L AS date) AS cs, CAST(%2$L AS date) AS ce,
         CAST(%3$L AS date) AS ps, CAST(%4$L AS date) AS pe
),
l AS (
  SELECT m.d, m.customer_id, m.inventory_id,
         CASE m.item_class WHEN '0' THEN 'NON-ITEM LINES' ELSE m.item_class END AS item_class,
         CASE m.rep WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN '0' THEN 'Unassigned' ELSE m.rep END AS rep,
         m.customer_name, m.description, m.rev, m.gp, m.qty,
         CASE WHEN m.d BETWEEN p.cs AND p.ce THEN 'c' ELSE 'p' END AS per
  FROM public.mv_sales_explorer m CROSS JOIN p
  WHERE (m.d BETWEEN p.cs AND p.ce OR m.d BETWEEN p.ps AND p.pe)
    AND (%5$s OR m.customer_id NOT IN ('C000007259', 'C000009702'))
),
cr0 AS (
  SELECT DISTINCT ON (customer_id) customer_id, rep AS then_rep
  FROM (SELECT customer_id, rep, SUM(rev) FILTER (WHERE per = 'c') AS rc, SUM(rev) AS rt FROM l GROUP BY 1, 2) x
  ORDER BY customer_id, rc DESC NULLS LAST, rt DESC
),
rec AS (
  SELECT DISTINCT ON (customer_id) customer_id, rep
  FROM (SELECT customer_id, CASE rep WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN '0' THEN 'Unassigned' ELSE rep END AS rep, SUM(rev) AS r
        FROM public.mv_sales_explorer WHERE d > CURRENT_DATE - 91 GROUP BY 1, 2) x
  WHERE r > 0
  ORDER BY customer_id, r DESC
),
ms AS (
  SELECT c.customer_id,
         MAX(CASE s.sp_name WHEN 'Kimberly Brown' THEN 'Oniel Carby' WHEN 'Tashelle Wilson' THEN 'Phobea Whorms' WHEN 'Shallet Marsh.' THEN 'Shallet Marsh' ELSE s.sp_name END) AS rep
  FROM public.customers c JOIN public.salespersons s ON CAST(s.acumatica_numeric_id AS text) = CAST(c.salesperson_id AS text)
  WHERE s.is_active
  GROUP BY 1
),
cr AS (
  SELECT cr0.customer_id,
         CASE WHEN CAST(%6$L AS text) = 'then' THEN cr0.then_rep ELSE COALESCE(rec.rep, ms.rep, 'No current rep') END AS crep
  FROM cr0 LEFT JOIN rec USING (customer_id) LEFT JOIN ms USING (customer_id)
),
cm AS (
  SELECT customer_id, MAX(customer_name) AS cname, MAX(NULLIF(TRIM(customer_class), '')) AS cls
  FROM public.customers GROUP BY 1
)
SELECT TO_CHAR(m.d, 'YYYY-MM') AS month,
  ROUND(SUM(m.rev)) AS rev,
  ROUND(SUM(m.gp)) AS gp,
  ROUND(100 * SUM(m.gp) / NULLIF(SUM(m.rev), 0), 1) AS gp_pct
FROM public.mv_sales_explorer m
LEFT JOIN cr USING (customer_id)
LEFT JOIN rec USING (customer_id)
LEFT JOIN ms USING (customer_id)
LEFT JOIN cm USING (customer_id)
WHERE (%5$s OR m.customer_id NOT IN ('C000007259', 'C000009702'))
  AND (CAST(%7$L AS text) IS NULL
       OR (CASE WHEN CAST(%6$L AS text) = 'then' THEN cr.crep ELSE COALESCE(rec.rep, ms.rep, 'No current rep') END) = CAST(%7$L AS text))
  AND (CAST(%8$L AS text) IS NULL OR COALESCE(cm.cls, 'UNASSIGNED') = CAST(%8$L AS text))
  AND (CAST(%9$L AS text) IS NULL OR (CASE m.item_class WHEN '0' THEN 'NON-ITEM LINES' ELSE m.item_class END) = CAST(%9$L AS text))
  AND (CAST(%10$L AS text) IS NULL OR m.customer_id = CAST(%10$L AS text))
  AND (CAST(%11$L AS text) IS NULL OR m.inventory_id = CAST(%11$L AS text))
GROUP BY 1
ORDER BY 1
$q$
    WHEN 'by_rep' THEN v_base || $q$
SELECT crep AS rep,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  COUNT(DISTINCT customer_id) FILTER (WHERE per = 'c') AS customers
FROM f
GROUP BY 1
HAVING SUM(rev) <> 0
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
    WHEN 'by_class' THEN v_base || $q$
SELECT cls AS customer_class,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  COUNT(DISTINCT customer_id) FILTER (WHERE per = 'c') AS customers
FROM f
GROUP BY 1
HAVING SUM(rev) <> 0
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
    WHEN 'by_cat' THEN v_base || $q$
SELECT item_class AS category,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  COUNT(DISTINCT customer_id) FILTER (WHERE per = 'c') AS customers
FROM f
GROUP BY 1
HAVING SUM(rev) <> 0
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
    WHEN 'customers' THEN v_base || $q$
SELECT customer_id, MAX(cname) AS customer, MAX(cls) AS customer_class, MAX(crep) AS rep,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  TO_CHAR(MAX(d), 'YYYY-MM-DD') AS last_order,
  COALESCE((SELECT MAX(k.channel) FROM public.ask_kam_accounts k WHERE k.customer_id = f.customer_id),
           (SELECT MAX(c.segment) FROM public.customers c WHERE c.customer_id = f.customer_id AND c.segment IN ('Key', 'Chain'))) AS channel,
  CASE WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) <= 0 THEN 'Lost'
       WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0) <= 0 THEN 'New'
       WHEN SUM(rev) FILTER (WHERE per = 'c') >= SUM(rev) FILTER (WHERE per = 'p') THEN 'Growing'
       ELSE 'Declining' END AS status
FROM f
GROUP BY customer_id
HAVING SUM(rev) <> 0
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
    WHEN 'products' THEN v_base || $q$
SELECT inventory_id AS sku, MAX(description) AS description, MAX(item_class) AS category,
  ROUND(SUM(qty) FILTER (WHERE per = 'c')) AS qty_c,
  ROUND(SUM(qty) FILTER (WHERE per = 'p')) AS qty_p,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  COUNT(DISTINCT customer_id) FILTER (WHERE per = 'c') AS customers,
  CASE WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) <= 0 THEN 'Lost'
       WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0) <= 0 THEN 'New'
       WHEN SUM(rev) FILTER (WHERE per = 'c') >= SUM(rev) FILTER (WHERE per = 'p') THEN 'Growing'
       ELSE 'Declining' END AS status
FROM f
WHERE inventory_id <> ''
GROUP BY inventory_id
HAVING POSITION('MOQ' IN UPPER(COALESCE(MAX(description), ''))) = 0 AND SUM(rev) <> 0
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
    WHEN 'cust_detail' THEN v_base || $q$
SELECT COALESCE(NULLIF(inventory_id, ''), '(no SKU)') AS sku, MAX(description) AS description, MAX(item_class) AS category,
  MAX(cname) AS customer,
  ROUND(SUM(qty) FILTER (WHERE per = 'c')) AS qty_c,
  ROUND(SUM(qty) FILTER (WHERE per = 'p')) AS qty_p,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  CASE WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) <= 0 THEN 'Lost'
       WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0) <= 0 THEN 'New'
       WHEN SUM(rev) FILTER (WHERE per = 'c') >= SUM(rev) FILTER (WHERE per = 'p') THEN 'Growing'
       ELSE 'Declining' END AS status
FROM f
WHERE customer_id = CAST(%10$L AS text)
GROUP BY 1
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
    WHEN 'sku_detail' THEN v_base || $q$
SELECT customer_id, MAX(cname) AS customer, MAX(cls) AS customer_class, MAX(crep) AS rep,
  MAX(description) AS description,
  ROUND(SUM(qty) FILTER (WHERE per = 'c')) AS qty_c,
  ROUND(SUM(qty) FILTER (WHERE per = 'p')) AS qty_p,
  ROUND(SUM(rev) FILTER (WHERE per = 'c')) AS rev_c,
  ROUND(SUM(rev) FILTER (WHERE per = 'p')) AS rev_p,
  ROUND(COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) - COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0)) AS chg,
  CASE WHEN SUM(rev) FILTER (WHERE per = 'p') > 0
       THEN ROUND(100 * (COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) / SUM(rev) FILTER (WHERE per = 'p') - 1), 1) END AS chg_pct,
  ROUND(100 * SUM(gp) FILTER (WHERE per = 'c') / NULLIF(SUM(rev) FILTER (WHERE per = 'c'), 0), 1) AS gp_pct,
  CASE WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'c'), 0) <= 0 THEN 'Lost'
       WHEN COALESCE(SUM(rev) FILTER (WHERE per = 'p'), 0) <= 0 THEN 'New'
       WHEN SUM(rev) FILTER (WHERE per = 'c') >= SUM(rev) FILTER (WHERE per = 'p') THEN 'Growing'
       ELSE 'Declining' END AS status
FROM f
WHERE inventory_id = CAST(%11$L AS text)
GROUP BY customer_id
HAVING SUM(rev) <> 0
ORDER BY rev_c DESC NULLS LAST, rev_p DESC NULLS LAST
$q$
  END;
  IF q IS NULL THEN RAISE EXCEPTION 'Unknown part %', p_part; END IF;
  q := format(q, v_start, v_end, v_pstart, v_pend, CASE WHEN v_usd THEN 'TRUE' ELSE 'FALSE' END, v_view,
              NULLIF(p->>'rep', ''), NULLIF(p->>'cls', ''), NULLIF(p->>'cat', ''), NULLIF(p->>'cust', ''), NULLIF(p->>'sku', ''));
  EXECUTE 'SELECT COALESCE(jsonb_agg(t), ''[]''::jsonb) FROM (' || q || ') t' INTO r;
  RETURN r;
END;
$fn$;

-- Refresh now: record the request; the cron job below does the rebuild within a minute.
CREATE OR REPLACE FUNCTION public.sales_explorer_request_refresh()
RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE t timestamptz := now();
BEGIN
  IF NOT public.sales_explorer_can() THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  UPDATE public.sales_explorer_meta SET requested_at = t WHERE id = 1;
  RETURN t;
END;
$$;

CREATE OR REPLACE FUNCTION public.sales_explorer_refresh_if_requested()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.sales_explorer_meta WHERE id = 1 AND requested_at > COALESCE(refreshed_at, '-infinity')) THEN
    PERFORM public.refresh_sales_explorer();
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.sales_explorer_can() FROM public, anon;
REVOKE ALL ON FUNCTION public.sales_explorer_data(text, jsonb) FROM public, anon;
REVOKE ALL ON FUNCTION public.sales_explorer_request_refresh() FROM public, anon;
REVOKE ALL ON FUNCTION public.sales_explorer_refresh_if_requested() FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.sales_explorer_can() TO authenticated;
GRANT EXECUTE ON FUNCTION public.sales_explorer_data(text, jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sales_explorer_request_refresh() TO authenticated;

SELECT cron.schedule('refresh-sales-explorer-on-request', '* * * * *',
  $$SET statement_timeout = '0'; SELECT public.sales_explorer_refresh_if_requested();$$);